def encode(s):
    """Compress runs of the same letter as letter + count, leaving out count 1."""
    result = []
    i = 0
    while i < len(s):
        char = s[i]
        count = 1
        i += 1
        while i < len(s) and s[i] == char:
            count += 1
            i += 1
        result.append(char)
        if count > 1:
            result.append(str(count))
    return ''.join(result)


def decode(s):
    """Undo encode, including counts with more than one digit."""
    result = []
    i = 0
    while i < len(s):
        char = s[i]
        i += 1
        start = i
        while i < len(s) and s[i].isdigit():
            i += 1
        count = int(s[start:i]) if start < i else 1
        result.append(char * count)
    return ''.join(result)
